def solve(inputs: dict) -> float:
    M = inputs['M']
    power = inputs['power']
    mod = inputs['mod']

    def matrix_mult(A, B, m):
        """Multiply two 2x2 matrices modulo m"""
        return [
            [(A[0][0] * B[0][0] + A[0][1] * B[1][0]) % m,
             (A[0][0] * B[0][1] + A[0][1] * B[1][1]) % m],
            [(A[1][0] * B[0][0] + A[1][1] * B[1][0]) % m,
             (A[1][0] * B[0][1] + A[1][1] * B[1][1]) % m]
        ]

    def matrix_power(M, n, m):
        """Compute M^n mod m using fast exponentiation"""
        if n == 1:
            return M

        result = [[1, 0], [0, 1]]  # Identity matrix
        base = [row[:] for row in M]  # Copy M

        while n > 0:
            if n % 2 == 1:
                result = matrix_mult(result, base, m)
            base = matrix_mult(base, base, m)
            n //= 2

        return result

    result = matrix_power(M, power, mod)
    total = sum(sum(row) for row in result)

    return float(total)
